import random

def random_fill_array(n, k):
    if n < k:
        raise ValueError("n must be at least k to include all integers from 0 to k-1")

    unique_numbers = set()
    while len(unique_numbers) < k:
        num = random.randint(0, k-1)
        unique_numbers.add(num)

    result_array = list(unique_numbers)
    while len(result_array) < n:
        num = random.randint(0, k-1)
        result_array.append(num)

    random.shuffle(result_array)
    return result_array

