def create_dict():
    cube_dict = {}
    prime_composite_dict = {'prime': [], 'composite': []}

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def get_prime_factors(n):
        factors = []
        d = 2
        while d * d <= n:
            while (n % d) == 0:
                factors.append(d)
                n //= d
            d += 1
        if n > 1:
            factors.append(n)
        return factors

    for i in range(1, 101):
        cube = i**3
        factors = get_prime_factors(i)
        cube_dict[i] = [cube, factors]
        if is_prime(i):
            prime_composite_dict['prime'].append(i)
        else:
            prime_composite_dict['composite'].append(i)

    return cube_dict, prime_composite_dict

# Example usage:
cube_dict, prime_composite_dict = create_dict()
print("Cube Dictionary:", cube_dict)
print("Prime Composite Dictionary:", prime_composite_dict)
```

This solution creates a dictionary with cubes and prime factors for numbers from 1 to 100 and categorizes them into prime and composite numbers.

