void triangle(int n) 
{ 
    // Outer loop to handle number of rows 
    // n in this case 
    for (int i = 0; i < n; i++) 
    { 
        // Calculate number of spaces needed for centering
        int numSpaces = (2 * n - 1 - (2 * i + 1)) / 2;

        // Print leading spaces
        for (int j = 0; j < numSpaces; j++) 
        { 
            cout << " "; 
        } 

        // Print 'x' characters
        for (int j = 0; j <= 2 * i; j++) 
        { 
            cout << "x"; 
        } 

        // Ending line after each row 
        cout << "\n"; 
    } 
} 

