    public static int getElementAtIndex(int[] arr, int index) {
        // Check if the array is empty
        if (arr.length == 0) {
            return -1;
        }

        // Check if the index is out of bounds
        if (index < 0 || index >= arr.length) {
            int sum = 0;
            for (int element : arr) {
                sum += element;
            }
            return sum;
        }

        // Return the element at the specified index
        return arr[index];
    }

