def wrap_in_box(text, padding, title):
    def split_text_into_lines(text):
        return text.split('\n')

    def find_max_line_length(lines):
        max_length = 0
        for line in lines:
            if len(line) > max_length:
                max_length = len(line)
        return max_length

    def create_border(width):
        return '-' * width

    def pad_lines(lines, padding, width):
        padded_lines = []
        for line in lines:
            padded_line = ' ' * padding + line + ' ' * padding
            if len(padded_line) > width:
                padded_line = padded_line[:width - 1]
            padded_lines.append(center_text(padded_line, width))
        return padded_lines

    def center_text(text, width):
        return text.center(width)

    lines = split_text_into_lines(text)
    max_line_length = find_max_line_length(lines)
    box_width = max_line_length + 2 * padding
    border = create_border(box_width)
    padded_lines = pad_lines(lines, padding, box_width)
    centered_title = center_text(title, box_width)

    print(border)
    print(centered_title)
    print(border)
    for line in padded_lines:
        print(line)
    print(border)

