```java
import java.util.ArrayList;
import java.util.List;

public class SimpleStringReverser {
    public static String reverse(String str) {
        List<Integer> nonAlphaPositions = new ArrayList<>();
        List<Character> alphaChars = new ArrayList<>();

        // Step 1: Identify non-alphabetic characters and store them
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (Character.isLetter(c)) {
                alphaChars.add(c);
            } else {
                nonAlphaPositions.add(i);
            }
        }

        // Step 2: Reverse the alphabetic characters
        int alphaIndex = alphaChars.size() - 1;

        // Step 3: Reconstruct the string
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < str.length(); i++) {
            if (nonAlphaPositions.contains(i)) {
                result.append(str.charAt(i));
            } else {
                result.append(alphaChars.get(alphaIndex--));
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        System.out.println(reverse("a,b$c")); // Expected output: "c,b$a"
        System.out.println(reverse("Hello, World!")); // Expected output: "dlroW ,olleH"
        System.out.println(reverse("Programming is fun!")); // Expected output: "gnimmargorP si nuf!"
    }
}
