    this.state = {
      name: '',
      age: '',
      nameError: '',
      ageError: '',
      isFormValid: false,
    };
  }

  handleChange = (event) => {
    const { name, value } = event.target;
    let nameError = '';
    let ageError = '';

    if (name === 'name') {
      if (!/^[A-Za-z]+$/.test(value)) {
        nameError = 'Name must contain only alphabetic characters.';
      }
    }

    if (name === 'age') {
      if (!/^\d+$/.test(value) || parseInt(value) < 0 || parseInt(value) > 120) {
        ageError = 'Age must be a number between 0 and 120.';
      }
    }

    this.setState({
      [name]: value,
      nameError,
      ageError,
      isFormValid: !nameError && !ageError && value !== ''
    });
  }

  handleSubmit = (event) => {
    event.preventDefault();
    if (this.state.isFormValid) {
      alert(`Name: ${this.state.name}, Age: ${this.state.age}`);
