            <tr>
                <th onclick="sortTable(0)">Column 1</th>
                <th onclick="sortTable(1)">Column 2</th>
                <th onclick="sortTable(2)">Column 3</th>
                <th onclick="sortTable(3)">Column 4</th>
            </tr>
        </thead>
        <tbody>
            <!-- Rows will be inserted here -->
        </tbody>
    </table>

    <script>
        const data = [
            { col1: "Data 1A", col2: "Data 1B", col3: "Data 1C", col4: "Data 1D" },
            { col1: "Data 2A", col2: "Data 2B", col3: "Data 2C", col4: "Data 2D" },
            { col1: "Data 3A", col2: "Data 3B", col3: "Data 3C", col4: "Data 3D" },
            { col1: "Data 4A", col2: "Data 4B", col3: "Data 4C", col4: "Data 4D" }
        ];

        function populateTable(data) {
            const tbody = document.querySelector("#dynamicTable tbody");
            tbody.innerHTML = ""; // Clear existing rows
            data.forEach(row => {
                const tr = document.createElement("tr");
                Object.values(row).forEach(cellText => {
                    const td = document.createElement("td");
                    td.textContent = cellText;
                    tr.appendChild(td);
                });
                tbody.appendChild(tr);
            });
        }

        let sortOrder = [true, true, true, true]; // Ascending order by default for all columns

        function sortTable(columnIndex) {
            const isAscending = sortOrder[columnIndex];
            data.sort((a, b) => {
                const aValue = a[`col${columnIndex + 1}`];
                const bValue = b[`col${columnIndex + 1}`];
                if (aValue < bValue) return isAscending ? -1 : 1;
                if (aValue > bValue) return isAscending ? 1 : -1;
                return 0;
            });
            sortOrder[columnIndex] = !isAscending; // Toggle sort order
            populateTable(data);
        }

        // Initial population of the table
        populateTable(data);
    </script>
</body>
</html>
```

