myApp.directive('highlight', function() {
  return {
    restrict: 'A',
    link: function(scope, element, attrs) {
      attrs.$observe('highlight', function(wordsWithColorsJSON) {
        var text = element[0].innerHTML;
        if (wordsWithColorsJSON) {
          var wordsWithColors = JSON.parse(wordsWithColorsJSON);
          var replacements = [];

          wordsWithColors.forEach(function(wordColorPair) {
            var word = wordColorPair.word;
