```java
import java.util.*;

public class ArraySort {
    public static int[] sortArray(int[] arr) {
        // Step 1: Count the frequency of each element
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : arr) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Step 2: Convert the map to a list of entries
        List<Map.Entry<Integer, Integer>> entryList = new ArrayList<>(frequencyMap.entrySet());

        // Step 3: Sort the list based on frequency and then by natural order
        Collections.sort(entryList, new Comparator<Map.Entry<Integer, Integer>>() {
            @Override
            public int compare(Map.Entry<Integer, Integer> o1, Map.Entry<Integer, Integer> o2) {
                int freqCompare = o1.getValue().compareTo(o2.getValue());
                if (freqCompare == 0) {
                    return o1.getKey().compareTo(o2.getKey());
                }
                return freqCompare;
            }
        });

        // Step 4: Extract the sorted elements into a new array
        int index = 0;
        int[] sortedArray = new int[arr.length];
        for (Map.Entry<Integer, Integer> entry : entryList) {
            int key = entry.getKey();
            int value = entry.getValue();
            for (int i = 0; i < value; i++) {
                sortedArray[index++] = key;
            }
        }

        return sortedArray;
    }

    public static void main(String[] args) {
        int[] arr = {4, 6, 2, 2, 6, 4, 4, 4};
        int[] sortedArr = sortArray(arr);
        System.out.println(Arrays.toString(sortedArr));
    }
}
```

This code will sort the array based on the frequency of elements first and then by their natural order if frequencies are the same. For example, given the input `{4, 6, 2, 2, 6, 4, 4, 4}`, the output will be `{2, 2, 6, 6, 4, 4, 4, 4}`.

