#include <iostream>
#include <string>
#include <unordered_set>
#include <cctype>

bool isIsogram(std::string s) 
{
    // Convert to lowercase
    for (char &c : s) {
        c = std::tolower(c);
    }

    // Filter out non-alphabetic characters
    std::string filtered;
    for (char c : s) {
        if (std::isalpha(c)) {
            filtered += c;
        }
    }

    // Check for repeating characters
    std::unordered_set<char> seen;
    for (char c : filtered) {
        if (seen.find(c) != seen.end()) {
            return false;
        }
        seen.insert(c);
    }

    return true;
}

int main() {
    std::string test = "Dermatoglyphics";
    std::cout << (isIsogram(test) ? "true" : "false") << std::endl; // Expected: true

    test = "moOse";
    std::cout << (isIsogram(test) ? "true" : "false") << std::endl; // Expected: false

    test = "isogram!";
    std::cout << (isIsogram(test) ? "true" : "false") << std::endl; // Expected: true

    return 0;
}
```

This solution handles the evolved problem by ensuring that the check for isograms is case-insensitive and ignores non-alphabetic characters, making it more complex than the original task.

